(()=>{const b=window.DriveQuizBank;if(!b)throw Error("Missing DriveQuizBank");b.questions.push(...[{"id":"rodrive-b-0451","batch":"10","category":"Categoria B","question":"Într-o intersecție nedirijată, conducătorul unui vehicul este obligat să acorde prioritate unui autovehicul destinat stingerii incendiilor, care circulă din stânga, având în funcțiune semnalizarea specială luminoasă și sonoră?","answers":["Nu, deoarece și în acest caz se aplică regula priorității de dreapta","Nu, deoarece autovehiculul destinat stingerii incendiilor nu face parte din categoria autovehiculelor cu regim prioritar","Da"],"correctIndices":[2],"correct":2,"explanation":"Semnalul special de avertizare cu lumină de culoare roșie obligă participanții la trafic să oprească imediat, pe acostament sau, în lipsa acestuia, cât mai aproape de marginea drumului sau bordura trotuarului, în sensul de deplasare. Atunci când urmează să intrați într-o intersecție, fie că este sau nu dirijată, aveți obligația de a opri și de a acorda prioritate de trecere autovehiculului destinat stingerii incendiilor, dacă acesta are în funcțiune luminile speciale de avertizare de culoare roșie și pe cele sonore. Trebuie știut că acestea trebuie să aibă ambele tipuri de semnalizare (luminoasă și sonoră) în funcțiune ca să beneficieze de această prioritate de trecere.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0451.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0451.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 451; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 450 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/intr-o-intersectie-nedirijata-conducatorul-unui-vehicul-este-obligat-sa-acorde-prioritate-unui-autovehicul-destinat-stingerii-incendiilor-ca","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"450","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0452","batch":"10","category":"Categoria B","question":"Cum poate fi menținută luminozitatea farurilor în condiții meteorologice nefavorabile?","answers":["Prin reglarea periodică a fasciculului luminos","Păstrând curate permanent farurile","Folosind numai lumina de drum"],"correctIndices":[1],"correct":1,"explanation":"Reglarea periodică a fasciculului luminos se poate face automat sau manual din autovehicul, în funcție de încărcătura mașinii în acel moment, fiind importantă pentru a nu-i stânjenii pe ceilalți participanți la trafic. Prin această reglare nu se rezolvă problema luminozității farurilor în condiții meteorologice nefavorabile. În condiții meteorologice nefavorabile luminozitatea farurilor poate fi menținută păstrând curate permanent farurile. Asigurarea stării tehnice și estetice ireproșabile se face prin: Folosirea luminilor de drum în permanență, adică faza lungă, nu va rezolva problema luminozității farurilor în condiții meteorologice nefavorabile, atât timp cât farurile sunt murdare și lumina nu poate pătrunde prin ele, caz în care tot la păstrarea acestora curate veți ajunge. Mai mult de atât, regulamentul rutier va interzice să folosiți luminile de drum (faza lungă) dacă din sens opus se apropie un vehicul de la o distanță mai mică de 200 de metri sau dacă în față, în acelasi sens, circulă alt vehicul la mai puțin de 100 de metri.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0452.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0452.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 452; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 451 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/cum-poate-fi-mentinuta-luminozitatea-farurilor-in-conditii-meteorologice-nefavorabile","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"451","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0453","batch":"10","category":"Categoria B","question":"La un accidentat cu corpi străini în interiorul plăgilor, procedura corectă este:","answers":["Extragerea corpilor străini din plăgi","Spălarea corpilor străini cu apă curată","Corpii străini nu se extrag din plăgi, întrucât se pot produce complicații"],"correctIndices":[2],"correct":2,"explanation":"În cazul în care un accidentat are corpi străini în interiorul plăgilor (rănilor), corpii străini nu se extrag din plăgi, întrucât se pot produce alte leziuni interne sau complicații. Corpii străini din interiorul plăgilor se vor extrage numai de catre personalul specializat.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0453.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0453.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 453; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 452 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/la-un-accidentat-cu-corpi-straini-in-interiorul-plagilor-procedura-corecta-este","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"452","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0454","batch":"10","category":"Categoria B","question":"Cum veți proceda corect în această intersecție, dacă semaforul este instalat deasupra intersecției?","answers":["Respectați semnificația semaforului, indiferent de direcția de mers, dacă acesta este dublat de un semafor însoțitor înainte de intersecție","Nu aveți obligația de a respecta indicația semnalelor luminoase plasate deasupra intersecției","Respectați indicațiile semaforului, dacă vizibilitatea vă permite acest lucru"],"correctIndices":[0],"correct":0,"explanation":"În situația dată, pe lângă semaforul instalat la intrarea în intersecție, întâlniți încă un semafor instalat deasupra intersecției, ambele indicând semnalul de culoare verde care permite trecerea. Semaforul instalat deasupra intersecției are rolul de a dubla semaforul principal, adică semaforul instalat la intrarea în intersecție, pentru o mai bună vizibilitate a semnalului semaforului principal. Prin urmare, în această situație puteți pătrunde în intersecție indiferent de direcția de mers dorită.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0454.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0454.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 454; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă o intersecție semaforizată cu mai multe benzi de circulație. Un semafor este plasat deasupra intersecției, care are culoarea verde spre șofer. În dreptul șoferului se află un semafor verde.","needsImageReview":true,"source":"RoDrive · ID 453 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/cum-veti-proceda-corect-in-aceasta-intersectie-daca-semaforul-este-instalat-deasupra-intersectiei","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"453","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_466.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0455","batch":"10","category":"Categoria B","question":"Oprirea hemoragiei se face prin legarea strânsă a brațului:","answers":["În dreptul rănii","Deasupra rănii","Sub rană"],"correctIndices":[1],"correct":1,"explanation":"Oprirea hemoragiei se face legând strâns brațul prin aplicarea unui garou,deasupra rănii. Se atașează neapărat un bilet pe care se notează numele victimei și ora exactă a aplicării garoului. Deși în trecut se recomanda slăbirea garoului la fiecare 15 minute pentru a permite alimentarea cu sânge a membrului, practică nu mai este recomandată în prezent, deoarece poate agrava starea victimei. Consultați personalul specializat prin apel 112 înainte de a efectua această manevră. Garoul este un cordon elastic utilizat pentru oprirea sângerărilor care nu pot fi controlate prin alte mijloace, este în mod obișnuit aplicat în cazul plăgilor membrelor. În lipsa unui garou propriu-zis, se pot folosi materiale improvizate, precum un fular, cordon, curea, cravată, șnur sau elastic. Acestea trebuie legate strânsdeasupra răniiși aplicate peste o bucată de fașă sau alt material moale, pentru a proteja pielea și a preveni leziunile suplimentare.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0455.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0455.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 455; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 454 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/oprirea-hemoragiei-se-face-prin-legarea-stransa-a-bratului","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"454","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0456","batch":"10","category":"Categoria B","question":"Ce obligații are conducătorul care intenționează să repună în mișcare vehiculul aflat între alte vehicule staționate?","answers":["Semnalizează sonor plecarea de pe loc, pentru a fi observat de cei care circulă în același sens","Semnalizează din timp plecarea de pe loc, se asigură că poate efectua manevra fără a perturba circulația sau fără a pune în pericol siguranța celorlalți participanți la trafic și acordă prioritate vehiculelor care circulă pe drumul public, indiferent de direcția de deplasare","Manevrează cu grijă vehiculul, pentru a nu lovi vehiculele din fața sau din spatele său, după care se repune în mișcare"],"correctIndices":[1],"correct":1,"explanation":"Atunci când doriți să repuneți în mișcare vehiculul, aveți obligația de a semnaliza din timp manevra, de a acorda prioritate de trecere tuturor vehiculelor care circulă pe drumul public, indiferent de direcția acestora de deplasare, și să vă asigurați că puteți efectua manevra fără a perturba circulația sau fără a pune în pericol siguranța celorlalți participanți la trafic.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0456.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0456.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 456; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 455 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/ce-obligatii-are-conducatorul-care-intentioneaza-sa-repuna-in-miscare-vehiculul-aflat-intre-alte-vehicule-stationate","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"455","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0457","batch":"10","category":"Categoria B","question":"Cum veți semnaliza faptul că vehiculul cu care circulați a rămas în pană pe partea carosabilă?","answers":["Prin folosirea luminilor de poziție","Prin instalarea triunghiurilor reflectorizante și prin folosirea luminilor de avarie","Prin purtarea vestei reflectorizante"],"correctIndices":[1],"correct":1,"explanation":"Legislația rutierăNUprevede obligația de a folosi luminile de poziție atunci când vehiculul cu care circulați a rămas în pană pe partea carosabilă. În situația în care rămâneți cu vehiculul în pană pe partea carosabilă, trebuie să îl scoateți imediat în afara părții carosabile. Iar dacă scoaterea acestuia în afara părții carosabile nu este posibilă, trebuie să îl deplasați lângă bordură ori acostament, semnalizând vehiculul prin punerea în funcțiune a luminilor de avarie și prin instalarea triunghiurilor reflectorizante la cel puțin 30 de metri înainte și după acesta. Legislația rutieră prevede că doar conducătorii vehiculelor și tractoarelor agricole sau forestiere cu masa maximă autorizatămai mare de 3,5 tonesă poarte,obligatoriu, echipament de protecție-avertizare fluorescent-reflectorizant, atunci când execută intervenții la vehiculul care se află pe partea carosabilă a drumului public. Această obligație nu o au și conducătorii vehiculelor din categoria B.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0457.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0457.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 457; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 456 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/cum-veti-semnaliza-faptul-ca-vehiculul-cu-care-circulati-a-ramas-in-pana-pe-partea-carosabila","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"456","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0458","batch":"10","category":"Categoria B","question":"Care este denumirea indicatorului?","answers":["Sens giratoriu","Punct de colectare a materialelor reciclabile","Presemnalizarea unei intersecții cu sens giratoriu"],"correctIndices":[2],"correct":2,"explanation":"Indicatorul se numește “Presemnalizarea intersecției cu sens giratoriu”, acest indicator avertizează conducătorii de vehicule că în intersecția care urmează circulația se desfășoară în sens giratoriu. După întâlnirea acestui indicator rutier, conducătorul auto va întâlni indicatorul de obligare \"Intersecție cu sens giratoriu\", intersecție în care vehiculele care circulă în interiorul acesteia vor avea prioritate față de cele care urmează să intre în intersecție.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0458.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0458.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 458; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă un indicator triunghiular cu margini roșii și săgeți negre ce formează un cerc, care semnalizează apropierea unui sens giratoriu.","needsImageReview":true,"source":"RoDrive · ID 457 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/care-este-denumirea-indicatorului","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"457","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_470.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0459","batch":"10","category":"Categoria B","question":"Autoturismul poate pătrunde în intersecția prezentată?","answers":["Da","Numai în caz de urgență","Nu, în intersecție poate pătrunde numai bicicleta"],"correctIndices":[2],"correct":2,"explanation":"În situația dată, polițistul rutier execută un semnal cu brațul stâng întins orizontal, acest semnal semnifică oprire pentru toți participanții la trafic a căror direcție inițială de deplasare se intersectează cu brațul acestuia, mai exact pentru cei care vin din fața polițistului. În această situație doar direcția de deplasare a autoturismului se intersectează cu brațul polițistului, fiind obligat să oprească. Prin urmare, autoturismul nu poate pătrunde în intersecție, însă biciclistul poate pătrunde în intersecție.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0459.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0459.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 459; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă o intersecție dirijată de un polițist rutier. Polițistul cu brațul stâng întins lateral indică oprirea pentru vehiculele care vin din față. Autoturismul albastru se află în fața polițistului.","needsImageReview":true,"source":"RoDrive · ID 458 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/autoturismul-poate-patrunde-in-intersectia-prezentata","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"458","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_471.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0460","batch":"10","category":"Categoria B","question":"Viteza de deplasare trebuie redusă:","answers":["La întâlnirea indicatorului „cedează trecerea“","Atunci când se circulă din direcția opusă tramvaielor, troleibuzelor și autobuzelor oprite în stație, pe drumurile cu o singură bandă pe sens","La întâlnirea indicatorului „prioritate față de circulația din sens invers“"],"correctIndices":[0],"correct":0,"explanation":"La întâlnirea indicatorului „Cedează trecerea” trebuiesă reduceți viteza de deplasareși să acordați prioritate de trecere vehiculelor care au acest drept, de regulă, vehiculelor care circulă pe drumul transversal. Nu aveți obligația de a reduce viteza de deplasare atunci când circulați din direcția opusă vehiculelor de transport public de persoane, chiar dacă acestea sunt oprite în stație. Dar dacă se trece foarte aproape de acestea, ca de exemplu atunci când drumul are o singură bandă pe fiecare sens, se recomandă,din punct de vedere la conduitei preventive, să se sporească atenția și, la nevoie, să se reducă viteza de deplasare. Nu aveți obligația de a reduce viteza de deplasare la întâlnirea indicatorului „Prioritate față de circulația din sens invers”, la întâlnirea acestui indicator aveți prioritate de trecere față de vehiculele care circulă din sens opus.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0460.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0460.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 460; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 459 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/viteza-de-deplasare-trebuie-redusa","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"459","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0461","batch":"10","category":"Categoria B","question":"Este permisă oprirea voluntară a unui vehicul pe trotuar?","answers":["Da, dacă se asigură un spațiu de cel puțin 1 m lățime pentru circulația pietonilor, iar semnalizarea rutieră permite această manevră","Legal, nu este prevăzut","Nu"],"correctIndices":[0],"correct":0,"explanation":"Este interzisă ocuparea trotuarelor cu vehicule imobilizate, iar când aceasta este permisa conform indicatoarelor sau marcajelor, lățimea minimă a trotuarului lăsat la dispoziția pietonilor trebuie să fie de cel puțin un metru.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0461.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0461.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 461; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 460 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/este-permisa-oprirea-voluntara-a-unui-vehicul-pe-trotuar","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"460","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0462","batch":"10","category":"Categoria B","question":"Accidentatul cu hemoragie externă trebuie așezat:","answers":["În așa fel încât rana care sângerează să fie mai jos decât planul corpului","Nu are importanță dacă rana este situată mai sus sau mai jos decât planul corpului","În așa fel încât rana sângerândă să fie mai sus decât nivelul corpului"],"correctIndices":[2],"correct":2,"explanation":"Accidentatul cu hemoragie externă trebuie așezat în așa fel încât rana sângerândă să fie mai sus decât nivelul corpului, ca presiunea arterială din zona hemoragiei să scadă. Hemoragia este scurgerea abundentă de sânge, internă sau externă, în urma ruperii sau tăierii peretelui unui vas sangvin. Aceasta este cauzată de lezarea integrității vasului, provocată de o traumă, liza purulentă a peretelui vascular, dereglarea chimismului sangvin. Hemoragiile sunt de două feluri: În funcție de cantitatea de sânge pierdută, putem distinge:","imageUrl":"/nivel-1/quiz-images/rodrive-all/0462.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0462.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 462; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 461 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/accidentatul-cu-hemoragie-externa-trebuie-asezat","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"461","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0463","batch":"10","category":"Categoria B","question":"După o ploaie torențială, este necesar să se păstreze o distanță considerabil mai mare față de vehiculul care circulă în față?","answers":["Da, întrucât spațiul de frânare se mărește","Nu, întrucât acest lucru duce la aglomerarea traficului","Da, deoarece nu se observă indicatoarele"],"correctIndices":[0],"correct":0,"explanation":"După o ploaie torențială sau în oricare altă situație în care partea carosabilă devine alunecoasă, distanță de siguranță față de vehiculul din față trebuie să fie considerabil mai mare, deoarece în aceste situații distanța de frânare crește semnificativ.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0463.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0463.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 463; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă o intersecție nesemaforizată din perspectiva unui șofer pe timp de ploaie, cu vizibilitate redusă. Șoferul se află aproape de vehiculul albastru. Vehiculul albastru virează la stânga, iar vehiculul galben circulă pe drumul principal.","needsImageReview":true,"source":"RoDrive · ID 462 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/dupa-o-ploaie-torentiala-este-necesar-sa-se-pastreze-o-distanta-considerabil-mai-mare-fata-de-vehiculul-care-circula-in-fata","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"462","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_475.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0464","batch":"10","category":"Categoria B","question":"Din punct de vedere al conduitei preventive, la ce vă puteți aștepta în această situație?","answers":["Biciclistul va opri","Biciclistul poate schimba direcția de mers spre stânga fără să se asigure","Biciclistul se va comporta corect"],"correctIndices":[1],"correct":1,"explanation":"La depășirea bicicletelor sau trotinetelor electrice există riscul ca cei care conduc aceste vehicule să se dezechilibreze sau să vireze brusc spre stânga fără să se asigure. Amintim că legislația rutieră impune, începând cu finalul anului 2021, următoarele reguli pentru depășirea bicicletelor și trotinetelor electrice. Pentru a asigura odistanță laterală de siguranță corespunzătoare, conducătorii de autovehicule (cu excepția autovehiculelor cu două roți), vor efectua manevra de depășire a bicicletelor sau a trotinetelor electrice respectând,pe lângă obligațiile privind manevra de depășire,și următoarele obligații,în funcție de viteza cu care aceștia se deplasează(art. 118 alin. 2 din Regulament): În concluzie, dacă te deplasezicu până la 50de km/h ești obligatmăcar să încalci marcajul, iar dacă te deplasezicu mai mult de 50 de km/hești obligatmăcar să treci cu jumătate din lățimea autovehiculului peste marcaj. Trebuie reținut că acestea de mai sus nu sunt doar recomandări, acestea sunt obligații, iar nerespectarea lor se sancționează conform legii. De reținut că în cazul în care un sector de drum are acest marcaj realizat culinie continuănu se mai poate efectua depășirea bicicletelor sau trotinetelor electrice, pentru căeste interzisă încălcarea sau trecerea peste acest marcaj cu linie continuă, iarpentru depășirea acestor vehicule este obligatorie încălcarea sau trecerea peste acest marcaj. Singura opțiune, regulamentară, este de a merge în spatele acestor vehicule până la terminarea marcajului cu line continuă și începerea marcajului cu linie discontinuă care se poate în","imageUrl":"/nivel-1/quiz-images/rodrive-all/0464.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0464.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 464; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea arată o situație de trafic urban din perspectiva unui șofer în care un biciclist circulă la dreapta carosabilului, aproape de șosea. Biciclistul este aproape de șofer.","needsImageReview":true,"source":"RoDrive · ID 463 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/din-punct-de-vedere-al-conduitei-preventive-la-ce-va-puteti-astepta-in-aceasta-situatie","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"463","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_476.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0465","batch":"10","category":"Categoria B","question":"Intenționați să virați la dreapta. Cum procedați cu pietonii care traversează regulamentar strada?","answers":["Virați fără ezitare, deoarece pietonii sunt obligați să aștepte","Acordați prioritate pietonilor care se află pe sensul dvs. de mers","Dați semnale de avertizare sonoră, pentru ca pietonii să vă permită trecerea"],"correctIndices":[1],"correct":1,"explanation":"Conducătorul de vehicul este obligat să acorde prioritate pietonului care traversează drumul public, prin loc special amenajat, marcat și semnalizat corespunzător ori la culoarea verde a semaforului destinat lui, atunci când acesta se afla pe sensul de mers al vehiculului. Deci în situația dată, virând către dreapta, vă intersectați cu pietoni care traversează drumul public regulamentar și aveți obligația de a le acorda prioritate de trecere.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0465.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0465.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 465; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă perspectiva unui șofer care se apropie de o trecere de pietoni semnalizată. Mai mulți pietoni traversează, având prioritate. Șoferul trebuie să reducă viteza și să oprească dacă este necesar. În dreapta, două autoturisme circulă, indicând un mediu urban aglomerat, ce necesită atenție sporită.","needsImageReview":true,"source":"RoDrive · ID 464 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/intentionati-sa-virati-la-dreapta-cum-procedati-cu-pietonii-care-traverseaza-regulamentar-strada","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"464","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_477.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0466","batch":"10","category":"Categoria B","question":"Conducătorii de vehicule aflați la o trecere la nivel cu o cale ferată industrială trebuie:","answers":["Să sporească atenția","Să respecte semnalele agentului de cale ferată","Să se asigure și să oprească, dacă observă că se apropie vreun tren"],"correctIndices":[1],"correct":1,"explanation":"Legislația rutieră spune că la apropierea și traversarea liniilor de cale ferată industrială trebuie să se dea dovadă de prudență sporită, însă varianta A de răspuns spune „să sporească atenția”, prin urmare, fiind diferență între aceste două exprimări, nu este considerat răspuns corect,să se dea dovadă de prudență sporită ≠ să sporească atenția. Conducătorii de vehicule aflați la o trecere la nivel cu o cale ferată industrială trebuie să dea dovadă de prudență sporită la apropierea și traversarea liniilor de cale ferată și sunt obligați să se conformeze semnificației semnalelor agentului de cale ferată. Atunci când pe calea ferată industrială se deplasează un vehicul feroviar, circulația trebuie dirijată de un agent de cale ferată. Prin urmare, dacă nu există un agent de cale ferată înseamnă că nu se va apropia niciun vehicul feroviar, caz în care nu trebuie să opriți. Dacă există agent de cale ferată, vă conformați semnalelor acestuia și veți opri doar dacă acesta vă face un semnal în acest sens. Prin urmare, oprirea nu este obligatorie, cu excepția cazului în care agentul de cale ferată vă adresează acest semnal.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0466.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0466.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 466; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 465 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/conducatorii-de-vehicule-aflati-la-o-trecere-la-nivel-cu-o-cale-ferata-industriala-trebuie","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"465","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0467","batch":"10","category":"Categoria B","question":"Aveți obligația de a opri imediat vehiculul la semnalele adresate de:","answers":["Ofițerii sau subofițerii jandarmeriei române","Polițiștii comunitari","Agenții de cale ferată, la trecerile la nivel"],"correctIndices":[2],"correct":2,"explanation":"Legislația rutieră nu prevede ca ofițerii sau subofițerii Jandarmeriei Române să poată adresa semnale de oprire. Prin urmare, aceștia nu pot adresa semnale de oprire conducătorilor de vehicule. Legislația rutieră nu prevede obligația de a opri la semnalele adresate de polițiștii comunitari. Din anul 2010 termenul „poliție comunitară” nu mai există în actele normative în vigoare. În acest moment termenul care se găsește în actele normative în vigoare este „poliție locală”. Pe lângă obligația de a opri la semnalele polițistului rutier, participanții la trafic sunt obligați să oprească imediat și la semnalele adresate în acest sens de către agenții de cale ferată, la trecerile la nivel. Aceștia din urmă pot efectua, pe lângă semnalele de oprire, și următoarele semnale: balansarea brațului în plan vertical, cu palma mâinii orientată către sol sau cu un mijloc de semnalizare, care semnifică reducerea vitezei, precum și rotirea vioaie a brațului, care semnifică mărirea vitezei de deplasare a vehiculelor, inclusiv grăbirea traversării drumului de către pietoni. Nerespectarea acestor semnale se sancționează cu amendă prevăzută în clasa a II-a de sancțiuni.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0467.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0467.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 467; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 466 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/aveti-obligatia-de-a-opri-imediat-vehiculul-la-semnalele-adresate-de","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"466","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0468","batch":"10","category":"Categoria B","question":"Sunteți obligat să folosiți luminile de întâlnire în timpul zilei:","answers":["Pe toate categoriile de drumuri publice","Numai pe drumurile județene, comunale și locale","Numai pe autostrăzi, drumuri expres și naționale europene"],"correctIndices":[0],"correct":0,"explanation":"Conducătorii de autovehicule și tractoare agricole sau forestiere sunt obligați să folosească și în timpul zilei luminile de întâlnire (faza scurtă)sauluminile pentru circulația diurnă „DRL”, atunci când circulă pe drumurile publice. Această obligație se va respecta indiferent de categoria drumului public pe care se circulă. Atragem atenția că această regulă este valabilă doar pe timpul zilei, nu și pe timpul nopții. Pentru a înțelege mai bine această regulă dăm următorul exemplu: Un conducător de autovehicul care circulăpe timpul zilei, în condiții normale, are obligația de a pune în funcțiunefie luminile de întâlnire(adică faza scurtă),fie luminile pentru circulația diurnă(DRL), după cum consideră acesta, ori poate chiar să le folosească pe ambele în același timp. Însă dacă acesta circulăpe timpul nopții, indiferent dacă drumul este sau nu iluminat, opțiunea de a alege să pună în funcțiune luminile pentru circulația diurnă (DRL) în locul luminilor de întâlnire (faza scurtă)NU mai este valabilăși este obligat să folosească luminile de întâlnire (faza scurtă) sau luminile de drum (faza lungă), în funcție de gradul de iluminare al drumului public pe care circulă. Mai multe informații despre obligația de a circula și pe timpul zilei cu luminile de întâlnire sau cu luminile pentru circulația diurnă în funcțiune găsiți aici -Obligația de a folosi luminile de întâlnire (faza scrută) sau luminile DRL pe timp de zi.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0468.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0468.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 468; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 467 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/sunteti-obligat-sa-folositi-luminile-de-intalnire-in-timpul-zilei","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"467","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0469","batch":"10","category":"Categoria B","question":"Care autovehicul va trece primul prin intersecție?","answers":["Autoturismul","Autocamionul","Autobuzul"],"correctIndices":[1],"correct":1,"explanation":"Intersecția este dirijata cu indicatoare de reglementare de prioritate, autobuzul întâlnește indicatorul „Cedează trecerea” și trebuie să le acorde prioritate de trecere celorlalte autovehicule. Autoturismul și autocamionul vin de pe drumuri cu prioritate și au prioritate de trecere, însă autoturismul schimbând direcția de mers către stânga trebuie să îi acorde autocamionului prioritate de dreapta, deoarece autocamionul îi vine din partea dreaptă. Deci primul prin intersecție va trece autocamionul, al doilea va trece autoturismul, iar ultimul va trece autobuzul.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0469.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0469.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 469; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă o intersecție semnalizată cu indicator triunghiular cu margini roșii, cedează trecerea pentru autobuzul care vine de jos și intenționează să meargă înainte. Autoturismul roșu, virează la stânga și vine din dreapta. Camionul se află în stânga și circulă înainte.","needsImageReview":true,"source":"RoDrive · ID 468 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/care-autovehicul-va-trece-primul-prin-intersectie","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"468","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_481.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0470","batch":"10","category":"Categoria B","question":"Când circulați pe un drum național european vă este interzisă:","answers":["Folosirea mijloacelor de avertizare sonoră","Remorcarea altui autovehicul","Staționarea voluntară pe partea carosabilă"],"correctIndices":[2],"correct":2,"explanation":"Legislația rutierănuprevede că folosirea mijloacelor de avertizare sonoră este interzisă pe un drum național european. Legislația rutierănuprevede că remorcarea unui autovehicul este interzisă pe un drum național european. Se interzice staționarea voluntară în toate cazurile în care este interzisă oprirea voluntară, iar oprirea voluntară vă este interzisă pe partea carosabilă a drumurilor național europene (E) și bineînțeles vă este interzisă și staționarea voluntară.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0470.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0470.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 470; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 469 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/cand-circulati-pe-un-drum-national-european-va-este-interzisa","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"469","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0471","batch":"10","category":"Categoria B","question":"Cum trebuie să procedați în situația prezentată?","answers":["Reduceți viteza și opriți la limita de vizibilitate maximă","Reduceți viteza și opriți în dreptul ultimului panou suplimentar","Reduceți viteza și vă asigurați că puteți traversa fără niciun pericol"],"correctIndices":[2],"correct":2,"explanation":"În situația dată întâlniți o trecere la nivel cu o cale ferată curentă prevăzută cu bariere și instalație de semnalizare automată, semnalul cu lumină albă intermitentă cu cadență lentă este în funcțiune, deci puteți traversa calea ferată, însă trebuie să circulați cu viteză redusă și să vă asigurați că din partea stângă sau din partea dreaptă nu se apropie un vehicul feroviar.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0471.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0471.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 471; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă o trecere la nivel cu calea ferată semnalizată cu bariere ridicate și lumini albe.","needsImageReview":true,"source":"RoDrive · ID 470 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/cum-trebuie-sa-procedati-in-situatia-prezentata","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"470","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_483.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0472","batch":"10","category":"Categoria B","question":"Cum vă comportați dacă intenționați să părăsiți autostrada în acest loc?","answers":["Frânați și ieșiți cu o viteză orientativă de 130 km/h","Semnalizați și vă angajați pe banda de ieșire","Măriți viteza, pentru a nu stânjeni vehiculele care circulă din spate"],"correctIndices":[1],"correct":1,"explanation":"Atunci când doriți să părăsiți autostrada, trebuie să semnalizați din timp manevra și să vă angajați pe banda de decelerare, după care reduceți viteza de deplasare. Banda de decelerare, cunoscută și sub denumirea de bandă de ieșire, este concepută special pentru a permite reducerea vitezei de deplasare fără a perturba fluxul de trafic de pe autostradă. Dorim să subliniem că în cazul în care încadrarea pe banda de decelerarenu s-a făcut din timp, este posibil să se ajungă în dreptul marcajului cu linie continuă care desparte prima bandă a autostrăzi de banda de decelerare, caz în care nu se mai poate face regulamentar trecerea pe banda de decelerare. În imaginea acestei întrebări nu se poate observa dacă autovehiculul se află în dreptul marcajului cu linie discontinuă ori în dreptul marcajului cu linie continuă. Însă presupunem că acesta se află în dreptul marcajului linie discontinuă, caz în care singura variantă de răspuns care poate fi corectă este varianta B. Celelalte două variante de răspuns nu pot fi corecte indiferent dacă autovehiculul se află în dreptul marcajului cu linie discontinuă ori în dreptul marcajului cu linie continuă.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0472.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0472.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 472; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă un drum expres cu indicatorul circular albastru cu săgeată spre dreapta-jos, ce indică ocolire pe partea dreaptă'. Șoferul inteționează să iasă de pe drumul expres.","needsImageReview":true,"source":"RoDrive · ID 471 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/cum-va-comportati-daca-intentionati-sa-parasiti-autostrada-in-acest-loc","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"471","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_484.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0473","batch":"10","category":"Categoria B","question":"Cum procedați în situația dată?","answers":["Circulați cu viteză redusă și, la nevoie, opriți pentru a permite autobuzului să reintre în trafic","Depășiți autobuzul","Sunteți obligat să opriți"],"correctIndices":[0],"correct":0,"explanation":"Atunci când vă apropiați de o stație pentru mijloace de transport public de persoaneprevăzută cu alveolă, circulând pe banda de lângă acostament sau bordură, iar autobuzul aflat oprit în stație semnalizează intenția de a ieși, aveți obligația de a reduce viteza și la nevoie să opriți pentru a-i permite acestuia să reintre în trafic. Trebuie să reținem că autobuzul al cărui conducător semnalizează intenția de a reintra în trafic din stația prevăzută cu alveolă are prioritateDOAR față de vehiculele care circulă din spatele acestuia, iar dacă drumul are mai multe benzi pe sens acesta are prioritateDOAR față de vehiculele care circulă din spatele acestuiape prima bandă.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0473.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0473.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 473; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă perspectiva unui șofer din trafic, având la dreapta sa un autobuz staționat pe banda dedicată transportului public. Șoferul se află pe banda de lângă acostament. Autobuzul intenționează să se reîncadreze la drum, semnalizând intenția pe banda pe care se află șoferul, ieșind din stație.","needsImageReview":true,"source":"RoDrive · ID 472 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/cum-procedati-in-situatia-data","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"472","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_485.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0474","batch":"10","category":"Categoria B","question":"Autoturismul a oprit regulamentar?","answers":["Da, deoarece drumul nu este intens circulat","Da, pentru că spațiul rămas este suficient pentru depășire","Nu, deoarece pe această categorie de drum sunt interzise oprirea și staționarea"],"correctIndices":[2],"correct":2,"explanation":"În situația din imagine autoturismul este oprit pe partea carosabilă a unui drum național european, conform indicatorului de culoare verde „E 15”, iar oprirea voluntară este interzisă pe partea carosabilă a drumurilor național europene. Prin urmare, autoturismul nu a oprit regulamentar.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0474.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0474.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 474; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă o situație pe un drum european cu două benzi de circulație. Un autoturism este oprit pe banda din sensul său de mers, iar un camion vrea să îl depășească.","needsImageReview":true,"source":"RoDrive · ID 473 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/autoturismul-a-oprit-regulamentar","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"473","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_486.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0475","batch":"10","category":"Categoria B","question":"Depășirea vehiculelor pe drumurile publice este interzisă:","answers":["Pe porțiunile de drum unde oprirea este interzisă","În intersecțiile cu circulație nedirijată","Pe drumurile publice cu o singură bandă pe sens"],"correctIndices":[1],"correct":1,"explanation":"Depășirea este permisă pe porțiunile de drum unde oprirea este interzisă. Legislația rutieră prevede exact inversul, interzice oprirea vehiculelor în locurile în care se interzice depășirea. Regulamentul rutier interzice depășirea vehiculelor în intersecțiile cu circulație nedirijată. Depășirea este permisă pe drumurile publice cu o singură bandă de circulație pe sens.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0475.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0475.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 475; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 474 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/depasirea-vehiculelor-pe-drumurile-publice-este-interzisa","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"474","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0476","batch":"10","category":"Categoria B","question":"Care este semnificația indicatorului?","answers":["„limitare de viteză“","„viteză minimă obligatorie“","„viteză maximă obligatorie“"],"correctIndices":[1],"correct":1,"explanation":"Indicatorul din imagine se numește “Viteza minimă obligatorie” și se montează în zona în care se impune o viteză de circulație minimă, în acest caz 40 de km/h. La întâlnirea acestui indicator conducătorii de autovehicule sunt obligați să circule cu o vitezăde peste 40 km/h, darsă nu depășească limita maximăde viteză admisă pe sectorul de drum respectiv. Sfârșitul zonei de acțiune a acestui indicator este anunțat de indicatorul ”Sfârșitul vitezei minime obligatorii”. Trebuie știut că în cazul în care pe sectorul de drum pe careviteza minimăa fost reglementată prin indicator sau prin alte mijloace, se circulă cu o viteză mai mică cu cel puțin 10 km/h sub limita minimă obligatorie stabilită,fără motiv, se sancționează contravențional cu amendă prevăzută în clasa I de sancțiuni.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0476.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0476.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 476; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Indicatorul circular albastru cu scris 40 alb din imagine arată limita minimă obligatorie de viteză, care este de 40 km/h.","needsImageReview":true,"source":"RoDrive · ID 475 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/care-este-semnificatia-indicatorului","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"475","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_488.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0477","batch":"10","category":"Categoria B","question":"Ce indicator urmează să fie întâlnit în intersecția aflată la 100 m de indicatorul 1?","answers":["Indicatorul 3","Indicatorul 2","Oricare dintre cele două indicatoare"],"correctIndices":[0],"correct":0,"explanation":"Indicatorul 1 are rolul de a avertiza conducătorii de vehicule că peste 100 de metri vor pătrunde într-o intersecție în care vor întâlni indicatorul \"Cedează trecerea\", adică indicatorul numărul 3. Deci după indicatorul numarul 1 veți întâlni în intersecția care urmează după 100 de metri indicatorul numărul 3. Intersecție în care sunteți obligat să reduceți viteza și să vă asigurați că pe drumul prioritar nu circulă alte vehicule, și abia apoi puteți pătrunde în intersecție. Dacă pe drumul prioritar circulă alte vehicule, sunteți obligat să opriți pentru a le acorda prioritate.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0477.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0477.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 477; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă trei indicatoare: (1) Indicator triunghiular cu margini roșii, sub care se află un panou adițional pe care scrie 100 (2) Indicator octogonal pe care scrie 'STOP', și (3) Indicator triunghiular cu margini roșii.","needsImageReview":true,"source":"RoDrive · ID 476 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/ce-indicator-urmeaza-sa-fie-intalnit-in-intersectia-aflata-la-100-m-de-indicatorul-1","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"476","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_489.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0478","batch":"10","category":"Categoria B","question":"Rotirea vioaie a brațului polițistului semnifică:","answers":["Mărirea vitezei de deplasare sau grăbirea traversării drumului de către pietoni","Oprirea temporară a circulației","Reducerea vitezei de deplasare"],"correctIndices":[0],"correct":0,"explanation":"Semnalul adresat de către polițistul rutier prin rotirea vioaie a brațului, semnifică mărirea vitezei de deplasare a vehiculelor sau grăbirea traversării drumului de către pietoni. Semnalele, indicațiile și dispozițiile polițistului rutier trebuie respectate cu prioritate față de regulile de circulație și față de semnificația diferitelor tipuri de mijloace de semnalizare rutieră.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0478.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0478.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 478; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 477 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/rotirea-vioaie-a-bratului-politistului-semnifica","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"477","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0479","batch":"10","category":"Categoria B","question":"Care sunt organele mobile ale mecanismului motor?","answers":["Blocul motor, cilindrii, chiulasa și carterul","Pistonul, segmenții, bolțul, biela, arborele cotit și volantul","Roțile directoare și cele tractoare"],"correctIndices":[1],"correct":1,"explanation":"Mecanismul motor are rolul de a transforma mișcarea rectilinie-alternativă a pistonului într-o mișcare de rotație a arborelui cotit. Mecanismul motor mai este numit si mecanismul bielă-manivelă. Organele mobile ale mecanismului motor sunt: pistonul, segmenții, bolțul, biela, arborele cotit și volantul. Organele fixe ale mecanismului motor sunt: blocul motor, chiulasa, baia de ulei și cilindrii.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0479.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0479.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 479; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 478 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/care-sunt-organele-mobile-ale-mecanismului-motor","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"478","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0480","batch":"10","category":"Categoria B","question":"Cum procedați dacă vă aflați în autoturismul roșu și observați că de pe drumul fără prioritate se apropie o coloană cu regim prioritar?","answers":["Vă continuați drumul, deoarece aveți prioritate de trecere în sensul giratoriu","Opriți și acordați prioritate coloanei cu regim prioritar","Virați la dreapta și părăsiți intersecția"],"correctIndices":[1],"correct":1,"explanation":"Coloana cu regim prioritarva avea întotdeauna în funcțiune semnale speciale de avertizare sonore și luminoase de culoare roșie, acestea obligă participanții la trafic să oprească în direcția de mers cât mai aproape de marginea drumului, iar atunci când este întâlnită în intersecții, participanții la trafic au obligația să îi acorde prioritate de trecere. Prin urmare, atunci când întâlniți o coloană cu regim de circulație prioritar, chiar dacă traversați o intersecție dirijată sau nedirijată, chiar dacă acea coloană cu regim prioritar vine de pe un drum prioritar sau nu, aveți obligația de a opri și de a acorda prioritate de trecere acesteia. Deci în situația dată, opriți și acordați prioritate de trecere coloanei cu regim prioritar, iar după trecerea acesteia vă puteți continua deplasarea, respectând regulile de circulație din acel loc.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0480.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0480.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 480; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă o intersecție giratorie semnalizată corespunzător. Vehiculul roșu intenționează să intre în sensul giratoriu și are prioritate. În sensul giratoriu intenționează să intre o coloană cu regim prioritar.","needsImageReview":true,"source":"RoDrive · ID 479 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/cum-procedati-daca-va-aflati-in-autoturismul-rosu-si-observati-ca-de-pe-drumul-fara-prioritate-se-apropie-o-coloana-cu-regim-prioritar","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"479","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_492.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0481","batch":"10","category":"Categoria B","question":"La semnalul polițistului având brațul stâng întins orizontal, orientat cu fața către autovehiculul care se apropie, conducătorul auto trebuie:","answers":["Să reducă viteza","Să oprească imediat","Să continue deplasarea"],"correctIndices":[1],"correct":1,"explanation":"Brațul stâng al polițistului rutier întins orizontal semnifică oprire pentru toți participanții la trafic a căror direcție de deplasare se intersectează cu brațul acestuia, mai exact pentru cei care vin din fața polițistului. Prin urmare, la semnalul polițistului orientat de regulă pe mijlocul drumului sau în mijlocul intersecției, cu fața către dumneavoastră și cu brațul stâng întins orizontal, trebuie să opriți, deoarece direcția dvs. de deplasare se intersectează cu brațul acestuia ridicat.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0481.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0481.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 481; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 480 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/la-semnalul-politistului-avand-bratul-stang-intins-orizontal-orientat-cu-fata-catre-autovehiculul-care-se-apropie-conducatorul-auto-trebuie","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"480","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0482","batch":"10","category":"Categoria B","question":"Semnificația indicatoarelor „Oprire“ și „Cedează trecerea“, instalate în intersecțiile semaforizate, trebuie respectată:","answers":["Atunci când traficul este redus","Atunci când semafoarele nu funcționează","Atunci când indicatoarele sunt instalate împreună cu semaforul pe același suport"],"correctIndices":[1],"correct":1,"explanation":"Indiferent de intensitatea traficului, se va respecta semnalul semaforului cu prioritate față de indicatoarele de reglementare de prioritate („Drum cu prioritate”, „Cedează trecerea” și „Oprire”). La intersecția dirijată prin semnale luminoase în care sunt instalate și indicatoare de reglementare de prioritate („Drum cu prioritate”, „Cedează trecerea” și „Oprire”), conducătorul de vehicul este obligat să respecte semnalele luminoase cu prioritate față de indicatoarele de reglementare de prioritate. Semnificația Indicatoarelor de reglementare de prioritate se va respecta în situația în care semafoarelenu funcționează, sau acesteafuncționează pe culoarea galbenă intermitentă. Indicatoarele de reglementare de prioritate se pot monta, fie pe același suport cu semaforul electric, fie pe un suport separat sau chiar pe un stâlp. Modul de amplasare a acestora nu influențează ordinea în care se respectă semafoarele și indicatoarele. Prin urmare, indiferent dacă indicatoarele sunt sau nu instalate pe același suport cu semaforul sau pe un alt suport, se va respecta semnalul semaforului cu prioritate față de indicatorul de reglementare de prioritate ce îl însoțește.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0482.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0482.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 482; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 481 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/semnificatia-indicatoarelor-oprire-si-cedeaza-trecerea-instalate-in-intersectiile-semaforizate-trebuie-respectata","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"481","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0483","batch":"10","category":"Categoria B","question":"Viteza va fi redusă până la limita legală în următoarele situații:","answers":["În perimetrul piețelor aglomerate","La întâlnirea indicatorului „oprire“","Când partea carosabilă este acoperită cu polei, gheață, zăpadă bătătorită, mâzgă sau piatră cubică umedă"],"correctIndices":[2],"correct":2,"explanation":"În perimetrul piețelor aglomerate nu este obligatorie reducerea vitezei și nici nu este prevăzută o anumită limită maximă de viteză. În aceste zone se vor respecta limitele maxime de viteză de pe respectivul sector de drum. Însă, din punct de vedere al conduitei preventive, se recomandă ca în zonele aglomerate să se reducă viteza de deplasare și să se sporească la maximum atenția, pentru a putea evita orice pericol în condiții de siguranță. La întâlnirea indicatorului „Oprire”este obligatorie oprirea pentru asigurare, chiar dacă pe drumul cu prioritate nu circulă în acel moment alte vehicule. Având în vedere că este vorba despreoprire obligatorie, nu mai poate fi vorba de reducerea vitezei până la limita legală. Aveți obligația de a circula cu o viteză care să nu depășească 30 km/h în localități sau 50 km/h în afara localităților, atunci când partea carosabilă este acoperită cu polei, gheață, zăpadă bătătorită, mâzgă sau piatră cubică umedă. În aceste situații riscul de a se produce accidente de circulație este foarte mare iar respectarea regimului legal de viteză ajută la evitarea eventualelor accidente de circulație.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0483.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0483.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 483; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 482 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/viteza-va-fi-redusa-pana-la-limita-legala-in-urmatoarele-situatii","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"482","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0484","batch":"10","category":"Categoria B","question":"La frânare, vehiculul derapează. Cum reacționați corect?","answers":["Frânați la maximum","Nu acționați frâna și rotiți volanul în sens invers derapării","Opriți motorul"],"correctIndices":[1],"correct":1,"explanation":"Dacă frânați la maximum veți accentua și mai mult derapajul și nu veți mai putea recăpăta aderența. În cazul în care autovehiculul intră în derapaj, se recomandăsa nu se bruscheze comenzile volanului, aderența între pneuri și calea de rulare fiind foarte scăzută. În aceste situații trebuiesă rotiți linvolanul în sens invers derapării și să nu acționați frâna pe cât posibil. Șoferii cu experiență accelerează ușor în aceste situații, doar atunci când în față nu sunt alte mașini sau obstacole, pentru a stabiliza autovehiculul. Această stabilizare cu ajutorul accelerării nu se recomandă celor fără experiență de conducere defensivă. Dacă opriți motorul o să se oprească toate sistemele de siguranță și cele care ajută la manevrarea autovehiculului, caz în care situația de va înrăutății.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0484.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0484.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 484; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 483 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/la-franare-vehiculul-derapeaza-cum-reactionati-corect","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"483","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0485","batch":"10","category":"Categoria B","question":"Atunci când victimei unui accident de circulație i s-au oprit bătăile inimii (stop cardiac), masajul cardiac se execută:","answers":["Prin apăsarea ritmică cu podul palmelor suprapuse a toracelui victimei, în dreptul inimii","Prin lovirea cu palmele a obrajilor victimei","Prin încrucișarea ritmică a brațelor victimei simultan cu respirația artificială"],"correctIndices":[0],"correct":0,"explanation":"Atunci când victimei unui accident de circulație i s-au oprit bătăile inimii (stop cardiac), trebuie efectuat masajul cardiac, acesta se execută prin apăsarea ritmică cu podul palmelor suprapuse a toracelui victimei, în dreptul inimii. Atenție!Stopul cardiac este atunci când victima nu are puls, adică victimei i s-au oprit bătăile inimii, dar aceasta încă respira. Dacă victima nu are puls și nici nu respiră, aceasta este înstop cardio-respirator. În cazul stopului cardio-respirator pe lângă masajul cardiac se execută și respirația artificială (respirația gură la gură).","imageUrl":"/nivel-1/quiz-images/rodrive-all/0485.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0485.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 485; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 484 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/atunci-cand-victimei-unui-accident-de-circulatie-i-s-au-oprit-bataile-inimii-stop-cardiac-masajul-cardiac-se-executa","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"484","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0486","batch":"10","category":"Categoria B","question":"În această situație veți circula cu:","answers":["Luminile de drum","Luminile de întâlnire","Luminile de poziție"],"correctIndices":[1],"correct":1,"explanation":"Conducătorii de autovehicule, tractoare agricole sau forestiere și tramvaie sunt obligați să folosească luminile de întâlnire (faza scurtă) atunci când plouă torențial, ninge abundent ori în alte condiții care reduc vizibilitatea pe drum, indiferent dacă se circulă pe timp de zi sau de noapte. În situația din imaginea întrebării se observă că circulați pe timp de ploaie torențială, caz în care aveți obligația de a circula cu luminile de întâlnire (faza scurtă) în funcțiune, chiar dacă se circulă pe timp de zi. Dorim să subliniem faptul că, dacă înainte de începerea ploii aveați în funcțiune luminile pentru circulația diurnă (DRL) în locul luminilor de întâlnire (faza scurtă), după începerea ploii această opțiunea de a se folosi luminile pentru circulația diurnă (DRL) în schimbul luminilor de întâlnire nu mai este valabilă și este obligatorie aprinderea luminilor de întâlnire (faza scurtă). Pentru a înțelege mai bine această regulă dăm următorul exemplu: Un conducător de autovehicul circulă pe timpul zilei,în condiții optime de vizibilitate, caz în care are obligația de a pune în funcțiunefie luminile de întâlnire(adică faza scurtă),fie luminile pentru circulația diurnă(DRL), după cum consideră acesta, ori poate chiar să le folosească pe ambele în același timp. Însă dacă acesta circulă pe timp de ploaie torențială, ninsoare abundentă ori în alte condiții care reduc vizibilitatea pe drum, opțiunea de a alege să pună în funcțiune luminile pentru circulația diurnă (DRL)în locul luminilor de întâlnire(faza scurtă)NUmai este valabilă pentru că legislația rutieră prevede că în ace","imageUrl":"/nivel-1/quiz-images/rodrive-all/0486.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0486.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 486; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă o situație de trafic pe timp de ploaie, cu vizibilitate redusă.","needsImageReview":true,"source":"RoDrive · ID 485 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/in-aceasta-situatie-veti-circula-cu","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"485","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_498.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0487","batch":"10","category":"Categoria B","question":"Precizați dacă presiunea din pneuri are efect asupra consumului de carburant:","answers":["Da","Nu","Numai în cazul vehiculelor de mare tonaj"],"correctIndices":[0],"correct":0,"explanation":"Umflarea insuficientă a pneurilor are ca efect creșterea consumului de combustibil. Rularea cu o presiune scăzută în pneuri duce la:","imageUrl":"/nivel-1/quiz-images/rodrive-all/0487.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0487.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 487; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă un autobuz de transport persoane staționat într-o benzinărie.","needsImageReview":true,"source":"RoDrive · ID 486 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/precizati-daca-presiunea-din-pneuri-are-efect-asupra-consumului-de-carburant","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"486","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_499.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0488","batch":"10","category":"Categoria B","question":"Semnalul galben intermitent al semaforului:","answers":["Anunță apariția semnalului roșu","Obligă conducătorii vehiculelor să reducă viteza și să circule respectând regulile de circulație aplicabile în acea intersecție","Interzice intrarea în intersecție"],"correctIndices":[1],"correct":1,"explanation":"Semnalul de culoare galbenă intermitent permite trecerea, însă conducătorul de vehicul este obligat să circule cu viteza redusă și să respecte semnificația semnalizării rutiere sau a regulilor de circulație aplicabile în acel loc. De exemplu, dacă lângă semaforul cu lumină galbenă intermitentă este instalat indicatorul de reglementare de prioritate “Oprire”, veți circula cu viteză redusă și veți respecta semnificația indicatorului “Oprire”, oprind și acordând prioritate de trecere celor care circulă pe drumul transversal.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0488.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0488.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 488; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 487 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/semnalul-galben-intermitent-al-semaforului","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"487","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0489","batch":"10","category":"Categoria B","question":"În care dintre situații nu este permisă mărirea vitezei de deplasare a autovehiculului / tractorului agricol sau forestier?","answers":["Când un alt vehicul s-a angajat în depășire","În zona de acțiune a indicatorului „viteză recomandată“","Când acesta circulă pe prima bandă, iar pe cea de lângă axul drumului se deplasează alte autovehicule, cu viteze superioare"],"correctIndices":[0],"correct":0,"explanation":"Vă este interzis să măriți viteza de deplasare atunci când un alt vehicul s-a angajat în depășirea vehiculului pe care îl conduceți. Legislația rutieră obligă ca atunci când urmează să fiți depășit,să nu mări viteza de deplasareșisă circulați cât mai aproape de marginea din dreapta a părții carosabile sau a benzii pe care vă deplasați. În zona de acțiune a indicatorului „Viteza recomandată” vă este permis să măriți viteza de deplasare. Acest indicator precizează care este viteza de deplasare considerată ca fiind optimă pentru a se circula în condiții de siguranță și pentru asigurarea unui trafic fluent.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0489.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0489.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 489; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 488 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/in-care-dintre-situatii-nu-este-permisa-marirea-vitezei-de-deplasare-a-autovehiculului-tractorului-agricol-sau-forestier","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"488","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0490","batch":"10","category":"Categoria B","question":"Ce obligații îi revin conducătorului de vehicul în momentul apropierii de o intersecție, dacă semnalul verde se schimbă cu cel galben?","answers":["Să grăbească traversarea","Să traverseze intersecția cu viteză redusă","Să oprească autovehiculul în fața marcajului de oprire sau a marcajului pentru trecerea pietonilor ori în dreptul semaforului"],"correctIndices":[2],"correct":2,"explanation":"În situația în care semnalul verde se schimbă cu cel galben, acest semnal anunță apariția semnalului de culoare roșie și obligă conducătorii de vehicule la oprire, iar dacă vehiculul se află prea aproape de intersecție la apariția semnalului galben și nu poate opri în condiții de siguranță, nu are obligația de a opri. Vehiculul trebuie oprit înaintea marcajului pentru oprire sau, după caz, pentru trecerea pietonilor, iar în lipsa acestuia, în dreptul semaforului.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0490.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0490.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 490; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 489 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/ce-obligatii-ii-revin-conducatorului-de-vehicul-in-momentul-apropierii-de-o-intersectie-daca-semnalul-verde-se-schimba-cu-cel-galben","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"489","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0491","batch":"10","category":"Categoria B","question":"Proprietarul unui vehicul este obligat:","answers":["Să declare autorităților schimbarea domiciliului în cel mult 24 de ore","Să declare organului fiscal valoarea poliței de asigurare auto","Să declare autorității emitente pierderea, furtul sau distrugerea certificatului de înmatriculare, în termen de 30 de zile de la constatare"],"correctIndices":[2],"correct":2,"explanation":"Proprietarul unui vehiculNUeste obligat să declare autorităților schimbarea domiciliului în cel mult 24 de ore. Proprietarul unui vehiculNUeste obligat să declare organului fiscal valoarea poliței de asigurare auto. Atenție!În anul2024, la examenul oficial, varianta C a acestei întrebări a fost modificată de la „să declare autorității emitente pierderea, furtul sau distrugerea certificatului de înmatriculare,în cel mult 48 de ore de la constatare” la „să declare autorității emitente pierderea, furtul sau distrugerea certificatului de înmatriculare,în termen de 30 de zile de la constatare”, iar varianta corectă a acestei întrebări este în continuare varianta C. În cazul proprietarului devehicul(inclusiv autovehicule, tractoare agricole sau forestiere, tramvaie, motociclete, mopede, etc.) acesta este obligat să solicite autorității competente eliberarea unui nou certificat de înmatriculare sau de înregistrare, în condițiile stabilite de autoritatea competentă, în termen de 30 de zile de la data declarării pierderii sau furtului acestuia. În cazul proprietarului deautovehiculsau deremorcă(doar în cazul acestor două) acesta este obligat să declare autorității emitente pierderea, furtul sau distrugerea certificatului de înmatriculare, în cel mult 48 de ore de la constatare. Prin urmare, fiind vorba despre proprietarul unuivehicul, acesta este obligat să declare autorității emitente pierderea, furtul sau distrugerea certificatului de înmatriculare, în termen de 30 de zile de la constatare.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0491.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0491.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 491; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 490 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/proprietarul-unui-vehicul-este-obligat","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"490","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0492","batch":"10","category":"Categoria B","question":"În care dintre situații se poate folosi semnalizarea cu mijloace de avertizare sonoră într-o localitate în care claxonatul este interzis?","answers":["La trecerile pentru pietoni","În intersecțiile nedirijate","Ori de câte ori este necesar, pentru evitarea unui pericol imediat"],"correctIndices":[2],"correct":2,"explanation":"Avertizarea sonoră se folosește ori de câte ori este necesar, pentru evitarea unui pericol imediat. Chiar dacă pe drumul pe care circulați este instalat indicatorul „Claxonarea interzisă” puteți folosi avertizarea sonoră pentru evitarea unui pericol imediat, acest caz face excepție de la interzicerea claxonării.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0492.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0492.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 492; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 491 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/in-care-dintre-situatii-se-poate-folosi-semnalizarea-cu-mijloace-de-avertizare-sonora-intr-o-localitate-in-care-claxonatul-este-interzis","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"491","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0493","batch":"10","category":"Categoria B","question":"Care dintre următoarele fapte constituie infracțiuni?","answers":["Nerespectarea semnalelor polițiștilor la trecerea coloanelor oficiale","Conducerea sub influența unor produse sau substanțe stupefiante sau a unor medicamente cu efecte similare","Depășirea limitei legale de viteză cu peste 50 km/h"],"correctIndices":[1],"correct":1,"explanation":"Nerespectarea regulilor de circulație la trecerea unei coloane oficiale ori intercalarea într-o astfel de coloană,se consideră contravențieși se sancționează cu amenda contravențională prevăzută în clasa a III-a de sancțiuni și cu aplicarea măsurii de reținere a permisului de conducere în vederea suspendării exercitării dreptului de a conduce pe o perioadă de 60 de zile. Nerespectarea acestor reguliNUse consideră infracțiune. Nerespectarea semnalelor, indicațiilor și dispozițiilor polițistului rutier aflat în exercitarea atribuțiilor de serviciu,se consideră contravențieși se sancționează cu amenda contravențională prevăzută în clasa a II-a de sancțiuni și cu aplicarea măsurii de reținere a permisului de conducere în vederea suspendării exercitării dreptului de a conduce pe o perioadă de 30 de zile. Nerespectarea acestor reguliNUse consideră infracțiune. Conducerea unui vehicul pentru care legea prevede obligativitatea deținerii permisului de conducere de către o persoană aflatăsub influența unor produse sau substanțe stupefiante sau a unor medicamente cu efecte similareeste consideratăinfracțiuneși se pedepsește penal, cu închisoare de la unu la 5 ani sau cu amendă. Depășirea limitei legale de viteză cu peste 50 km/hNUse consideră infracțiune, aceasta este consideratăcontravențieși se sancționează cu amenda contravențională din clasa a IV-a și cu aplicarea măsurii de reținere a permisului de conducere în vederea suspendării exercitării dreptului de a conduce pe o perioadă de 90 de zile pentru depășirea cu peste 50 km/h sau 120 de zile pentru depășirea cu peste 70 km/h.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0493.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0493.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 493; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 492 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/care-dintre-urmatoarele-fapte-constituie-infractiuni","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"492","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0494","batch":"10","category":"Categoria B","question":"Ce semnifică panoul adițional?","answers":["Începutul zonei de acțiune a indicatorului „staționarea interzisă“","Începutul zonei de acțiune a indicatorului „oprirea interzisă“","Staționarea este interzisă până la indicator"],"correctIndices":[1],"correct":1,"explanation":"În cazul în care indicatorul \"Oprirea interzisă\" este instalat singur, oprirea este interzisă din dreptul lui și până la colțul primei intersecții, indiferent de lungimea sectorului. Acest indicator poate fi însoțit și de panouri adiționale: Prin urmare, în această situație întâlniți indicatorul “Oprirea interzisă” însoțit de panoul adițional “Săgeată cu vârful în sus”, acest panou adițional indică începutul zonei în care oprirea voluntară a vehiculelor este interzisă.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0494.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0494.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 494; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă un drum urban cu indicatorul circular albastru cu margini roșii și un X roșu. În plus, se află un panou adițional sub acesta, cu o săgeată îndreptată spre sus.","needsImageReview":true,"source":"RoDrive · ID 493 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/ce-semnifica-panoul-aditional","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"493","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_506.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0495","batch":"10","category":"Categoria B","question":"În situația dată, pentru a vă semnaliza prezența, veți schimba alternativ luminile de drum cu luminile de întâlnire?","answers":["Da, după trecerea autocamionului","Nu","Se folosesc numai luminile de drum"],"correctIndices":[0],"correct":0,"explanation":"În situația dată întâlniți indicatorul „Intersecție de drumuri”, acest indicator vă avertizează ca urmează o intersecție nedirijata de două drumuri de aceeași categorie. Legislația rutieră obligă ca atunci când circulațipe timpul nopțiisau în condiții de vizibilitate redusă print-o astfel de intersecție, mai exact prin intersecțiile care nu sunt dirijate prin semafoare sau de către polițiști, aveți obligația de a vă semnaliza prezența prin schimbarea alternativă a luminilor de întâlnire (faza scurtă) cu luminile de drum (faza lungă). Acest tip de semnalizare nu se poate efectua în cazul în care se apropie din sens opus un alt vehicul de la cel puțin 200 de metri, pentru a nu-l deranja pe acesta cu lumina de drum (faza lungă), lumină care este foarte puternică. Prin urmare, în situația dată trebuie să așteptați trecerea autocamionului, după care vă semnalizați prezența prin a schimba alternativ luminile de întâlnire (faza scurtă) cu luminile de drum (faza lungă).","imageUrl":"/nivel-1/quiz-images/rodrive-all/0495.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0495.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 495; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă un drum din perspectiva unui șofer, pe timp de noapte, care se află în fața unui indicatorul triunghiular cu margine roșie și un X negru în interior ce semnifică intersecție cu un drum fără prioritate. Pe sensul opus se află un camion, în apropierea șoferului.","needsImageReview":true,"source":"RoDrive · ID 494 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/in-situatia-data-pentru-a-va-semnaliza-prezenta-veti-schimba-alternativ-luminile-de-drum-cu-luminile-de-intalnire","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"494","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_805.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0496","batch":"10","category":"Categoria B","question":"Sunteți obligat să vă supuneți recoltării probelor biologice, în cazul unui accident de circulație din care a rezultat moartea sau vătămarea integrității corporale ori a sănătății unor persoane?","answers":["Da, dar numai dacă sunteți vinovat de producerea accidentului","Nu, dacă ați fost testat cu un aparat autorizat","Da"],"correctIndices":[2],"correct":2,"explanation":"Dacă ați fost implicat într-un accident de circulație în urma căruia a rezultat moartea sau vătămarea integrității corporale ori a sănătății unei persoane, aveți obligația să vă supuneți recoltării mostrelor biologice în vederea stabilirii alcoolemiei sau, după caz, a consumului de substanțe psihoactive, precum și să luați măsuri de anunțare imediată a poliției, să nu modificați sau să ștergeți urmele accidentului și să nu părăsiți locul faptei.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0496.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0496.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 496; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 495 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/sunteti-obligat-sa-va-supuneti-recoltarii-probelor-biologice-in-cazul-unui-accident-de-circulatie-din-care-a-rezultat-moartea-sau-vatamarea-","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"495","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0497","batch":"10","category":"Categoria B","question":"Substanțele antiseptice se folosesc pentru:","answers":["Dezinfectarea rănilor","Calmarea durerilor","Oprirea hemoragiei"],"correctIndices":[0],"correct":0,"explanation":"Substanțele antiseptice sunt substanțe chimice folosite pentru a preveni sau reduce riscul de infecții, prin distrugerea sau oprirea creșterii microorganismelor dăunătoare. Ele sunt utilizate pentru curățarea rănilor, asigurând un mediu igienic și sigur, ceea ce ajută la prevenirea contaminării și a eventualelor complicații.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0497.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0497.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 497; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 496 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/substantele-antiseptice-se-folosesc-pentru","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"496","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0498","batch":"10","category":"Categoria B","question":"Se consideră depășire faptul că vehiculele de pe o bandă circulă mai repede decât vehiculele de pe celelalte benzi?","answers":["Nu","Nu, dacă se circulă pe banda din stânga","Da, dacă se circulă pe banda din dreapta"],"correctIndices":[0],"correct":0,"explanation":"Depășirea este manevra prin care un vehicul trece înaintea altui vehicul ori pe lângă un obstacol, aflat pe același sens de circulație, prin schimbarea direcției de mers și ieșirea de pe banda de circulație sau din șirul de vehicule în care s-a aflat inițial. În cazul în care un vehicul circulă mai repede pe una dintre benzi decât vehiculele care circulă pe altă bandă în același sens de circulație, nu se consideră depășire, indiferent pe ce bandă se deplasează vehiculul care circulă mai repede.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0498.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0498.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 498; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"","needsImageReview":false,"source":"RoDrive · ID 497 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/se-considera-depasire-faptul-ca-vehiculele-de-pe-o-banda-circula-mai-repede-decat-vehiculele-de-pe-celelalte-benzi","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/questions_without_images.json","sourceQuestionId":"497","referenceImageUrl":null,"license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0499","batch":"10","category":"Categoria B","question":"În situația dată, aveți obligația:","answers":["Să opriți, să vă asigurați și să acordați prioritate de trecere înainte de a traversa intersecția","Nu aveți nicio obligație, întrucât circulați pe un drum prioritar","Traversați o dată cu autoutilitara și autoturismul, deoarece acestea s-au asigurat"],"correctIndices":[0],"correct":0,"explanation":"În situația dată întâlniți indicatorul „Oprire”. La întâlnirea acestui indicator aveți obligația de a opri, vă asigurați și acordați prioritate tuturor vehiculelor care circulă pe drumul prioritar.Oprirea este obligatorie, chiar dacă pe drumul prioritar nu circulă în acel moment vehicule, după care puteți pătrunde în intersecție. Nu circulați pe un drum prioritar, din contră,circulați pe un drum fără prioritate, acest lucru este confirmat de indicatorul „Oprire”. Nu trebuie să vă încredeți niciodată în faptul că ceilalți participanți la trafic s-au asigurat sau să va bazați în totalitate pe semnalele date de aceștia, asigurarea se va face individual. Mai mult de atât, indicatorul „Oprire” obligă la oprire, indiferent de situație, caz în care nu puteți intra în intersecție o dată cu autoutilitara și autoturismul.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0499.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0499.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 499; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă o intersecție semnalizată din perspectiva unui șofer cu indicatorul octogonal roșu pe care scrie cu alb 'STOP'. Intersecția prezintă o trecere de pietoni. Vehiculul din față se angajează în traversarea intersecției. Șoferul intră în intersecție.","needsImageReview":true,"source":"RoDrive · ID 498 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/in-situatia-data-aveti-obligatia","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"498","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_511.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"},{"id":"rodrive-b-0500","batch":"10","category":"Categoria B","question":"Autobuzul din față semnalizează ieșirea din stația prevăzută cu alveolă. Cum trebuie să procedați?","answers":["Îl ocoliți cât mai mult, pentru a proteja pietonii","Reduceți viteza și la nevoie opriți, pentru a permite plecarea din stație a autobuzului","Vă continuați deplasarea, deoarece nu aveți restricții"],"correctIndices":[1],"correct":1,"explanation":"În situația dată se observă că autobuzul intenționează să iasă din stația prevăzută cu alveolă, iar dumneavoastră,pentru că vă deplasați în spatele acestuiape banda de lângă bordură, aveți obligația de a reduce viteza și, la nevoie, să opriți pentru a-i permite acestuia să reintre în trafic. Trebuie să reținem că autobuzul al cărui conducător semnalizează intenția de a reintra în trafic din stația prevăzută cu alveolă are prioritateDOAR față de vehiculele care circulă din spatele acestuia, iar dacă drumul are mai multe benzi pe sens acesta are prioritateDOAR față de vehiculele care circulă din spatele acestuiape prima bandă.","imageUrl":"/nivel-1/quiz-images/rodrive-all/0500.svg","imagePage":"","fallbackImage":"/nivel-1/quiz-images/rodrive-all/0500.svg","imageAlt":"Schemă originală orientativă pentru întrebarea 500; verifică imaginea de referință atunci când întrebarea depinde de detaliile vizuale.","imageCredit":"Pixel Drive · schemă originală orientativă (nu imagine oficială)","imageDescription":"Imaginea prezintă un autobuz staționat pe partea dreaptă a drumului, care semnalizează ieșirea din stația prevăzută cu alveolă. Este imposibilă depășirea autobuzului.","needsImageReview":true,"source":"RoDrive · ID 499 · CC BY-SA 4.0","url":"https://huggingface.co/datasets/AnonymousDrive/RoDrive","sourceUrl":"https://www.scoalarutiera.ro/cautare/autobuzul-din-fata-semnalizeaza-iesirea-din-statia-prevazuta-cu-alveola-cum-trebuie-sa-procedati","sourceLabel":"Caută întrebarea pe Școala Rutieră","originalDatasetUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDrive/blob/main/anon_questions_with_images.json","sourceQuestionId":"499","referenceImageUrl":"https://huggingface.co/datasets/AnonymousDrive/RoDriveImages/resolve/main/Cat_B_poz_512.jpg","license":"CC BY-SA 4.0","licenseUrl":"https://creativecommons.org/licenses/by-sa/4.0/"}]);})();
